from pathlib import Path
import json,html,hashlib,csv,io

def require(condition, message):
    if not condition:
        raise ValueError(message)

def validate(content):
    require(content["status"] == "prepared-not-field-validated", "Invalid prepared rehearsal content: 5")
    ids=[section["id"] for section in content["sections"]]
    require(len(ids)==len(set(ids)) and {"rehearsal","comparison","synthetic"}.issubset(ids), "Invalid prepared rehearsal content: 7")
    rehearsal=content["rehearsal"]
    require(rehearsal["status"] == "prepared-not-observed", "Invalid prepared rehearsal content: 9")
    require(len(rehearsal["scenarios"]) == 8, "Invalid prepared rehearsal content: 10")
    require(len({case["id"] for case in rehearsal["scenarios"]}) == 8, "Invalid prepared rehearsal content: 11")
    for case in rehearsal["scenarios"]:
        require(case["dataKind"] == "synthetic-adult-rehearsal" and case["actualResult"] is None, "Invalid prepared rehearsal content: 13")
        require(case["observationStatus"] == "not-observed", "Invalid prepared rehearsal content: 14")
        for field in ("title","sourceText","task"):
            require(set(case[field]) == {"vi","en"} and all(isinstance(v,str) and v.strip() for v in case[field].values()), "Invalid prepared rehearsal content: 16")
    template=rehearsal["recordTemplate"]
    require(template["dataKind"] == "manual-unverified-observation", "Template must retain manual/unverified provenance")
    require(all(value is None for key,value in template.items() if key not in {"dataKind","metrics","choiceMode","observationStatus"}), "Prepared observation template must remain blank; unknown values are null")
    require(template["observationStatus"] == "not-observed" and template["choiceMode"] == "not-chosen", "Invalid prepared rehearsal content: 18")
    require(template["rescueCount"] is None and template["durationSeconds"] is None, "Invalid prepared rehearsal content: 19")
    require(template["observerConfirmation"] is None, "Invalid prepared rehearsal content: 20")
    require(set(template["metrics"]) == {f"M{i}" for i in range(1,7)}, "Invalid prepared rehearsal content: 21")
    require(all(row == {"status":"not-observed","evidence":None} for row in template["metrics"].values()), "Invalid prepared rehearsal content: 22")

def printable_sheet(content,lang):
    labels={key:value[lang] for key,value in content['rehearsal']['sheetLabels'].items()}
    esc=lambda value:html.escape(str(value),quote=True)
    columns=('original','proposal','choice','scene','evidence')
    rows='<tr>'+''.join('<td>________________<br>________________</td>' for _ in columns)+'</tr>'
    metrics=''.join('<tr><td>'+key+'</td><td>'+esc(labels['notObserved'])+'</td><td>________________</td></tr>' for key in content['rehearsal']['recordTemplate']['metrics'])
    return '<div class="record-sheet"><h3>'+esc(labels['caption'])+'</h3><p>'+esc(labels['boundary'])+'</p><div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(labels[key])+'</th>' for key in columns)+'</tr></thead><tbody>'+rows*3+'</tbody></table></div><div class="table-wrap"><table><thead><tr><th>'+esc(labels['metric'])+'</th><th>'+esc(labels['status'])+'</th><th>'+esc(labels['evidence'])+'</th></tr></thead><tbody>'+metrics+'</tbody></table></div><p>'+esc(labels['rescue'])+'</p><p>'+esc(labels['duration'])+'</p><p>'+esc(labels['metadata'])+'</p></div>'

